import { hideChartPopover, showChartPopover } from "../chart-board/board-util";

function generateTooltipContentRow(obj) {
	let infoBlock = null;
	if (Array.isArray(obj.data)) {
		infoBlock = obj.data
			.map(
				(r) =>
					`<div class="chart-bar__popover">
        <div>
          <div style="background:${obj.color};"></div>
          ${r.key}
        </div>
        <div>
          ${r.value}
        </div>
      </div>`,
			)
			.join("");
	} else {
		infoBlock = `
      <div class="chart-bar__popover">
        <div>
          <div style="background:${obj.color};"></div>
          ${obj.data.indexValue}
        </div>
        <div>
          ${obj.data.value}
        </div>
      </div>
    `;
	}
	return infoBlock;
}

const toggleBarItemPopover = (
	tooltipRef,
	event?,
	node?,
	customTooltipFunc?,
) => {
	if (event && tooltipRef) {
		showChartPopover(
			tooltipRef,
			node,
			event,
			customTooltipFunc,
			generateTooltipContentRow,
		);
	} else if (tooltipRef) {
		hideChartPopover(tooltipRef);
	}
};

const toggleBarLegendPopover = (
	tooltipRef,
	event?,
	id?: string,
	fill?: string,
	userConfig?,
) => {
	if (event && id && fill && userConfig) {
		const curDataAry = userConfig.data
			.filter((r) => Object.prototype.hasOwnProperty.call(r, id))
			.map((r) => ({
				key: r[userConfig.indexBy],
				value: r[id],
				formattedValue: userConfig.tooltip?.(r[id]) ?? r[id],
			}));

		showChartPopover(
			tooltipRef,
			{ id, data: curDataAry, color: fill },
			event,
			userConfig.legendTooltip,
			generateTooltipContentRow,
		);
	} else {
		hideChartPopover(tooltipRef);
	}
};

const convertBarDataToCSV = (arr) => {
	const headers = Array.from(
		arr.reduce((total, cur) => {
			const keys = Object.keys(cur);
			keys.forEach((r) => total.add(r));
			return total;
		}, new Set()),
	) as string[];

	const title = `${headers.join(",")}\n`;

	const result = arr
		.map((it) => {
			const line = headers.reduce((total, cur, idx) => {
				let row = total + (it[cur] || '""');

				if (idx !== headers.length - 1) {
					row += ",";
				}
				return row;
			}, "");
			return line;
		})
		.join("\n");

	return title + result;
};

export { toggleBarItemPopover, toggleBarLegendPopover, convertBarDataToCSV };
